import {CATALOG} from './catalog.js';
import {THEMES,foodArt} from './visuals.js';
import {bannerMarkup,initBannerViewer} from './banner.js?v=5';
import {STATUS,CATEGORIES,STOCK,clone,bangkokDate,parseBaht,groupsFor,choiceAvailable,baseAvailable,menuReady,displayPrices,lineFor,createOrder,advanceOrder,payOrder,cancelOrder,refundOrder,totals,closeDay,changeStock,stockImpact,openShop,updateDish,uuid,addDish,publishDish,unpublishDish,dishConfigured,visibleMenu} from './core.js?v=3';
import {PracticeRepository} from './storage.js?v=3';
import {PlatformRepository,liveConfigured,launchMode} from './platform.js?v=6';
const $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>Number.isInteger(n)?new Intl.NumberFormat('th-TH',{maximumFractionDigits:2}).format(n/100)+' บาท':'รอกำหนดราคา';
const inputMoney=n=>Number.isInteger(n)?String(n/100):'';
const time=s=>new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',hour:'2-digit',minute:'2-digit'}).format(new Date(s));
const day=s=>new Intl.DateTimeFormat('th-TH',{timeZone:'Asia/Bangkok',day:'numeric',month:'short'}).format(new Date(s+'T12:00:00+07:00'));
const icons={bag:'<path d="M5 7h14l1 14H4L5 7Z"/><path d="M8 8V6a4 4 0 0 1 8 0v2"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',back:'<path d="M20 12H4m6-6-6 6 6 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',bowl:'<path d="M3 10h18c0 6-4 10-9 10S3 16 3 10ZM7 22h10M9 2c-3 3 2 4 0 6m6-7c-3 3 3 4 0 7"/>',plus:'<path d="M12 5v14M5 12h14"/>',search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',list:'<path d="M8 5h13M8 12h13M8 19h13M3 5h.01M3 12h.01M3 19h.01"/>',menu:'<path d="M4 4h6v6H4zm10 0h6v6h-6zM4 14h6v6H4zm10 0h6v6h-6z"/>',cash:'<rect x="3" y="5" width="18" height="14" rx="2"/><circle cx="12" cy="12" r="3"/><path d="M6 9h.01M18 15h.01"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9 9a3 3 0 1 1 4 3c-1 0-1 1-1 2m0 3h.01"/>',check:'<path d="m5 12 4 4L20 5"/>',image:'<rect x="3" y="3" width="18" height="18" rx="2"/><circle cx="8" cy="8" r="1"/><path d="m21 16-6-6L4 21"/>',home:'<path d="m3 10 9-7 9 7M5 9v12h14V9M9 21v-7h6v7"/>'};
Object.assign(icons,{receipt:'<path d="M5 3h14v18l-3-2-4 2-4-2-3 2V3Z"/><path d="M8 7h8M8 11h8M8 15h5"/>',undo:'<path d="M3 9h10a7 7 0 1 1-6 11M3 9l5-5M3 9l5 5"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 3"/>',fire:'<path d="M13 3c4 6-3 5 1 11 2-1 3-3 3-5 8 9 1 13-5 13S1 16 7 9c-1 5 2 5 3 4 3-3-1-5 3-10Z"/>'});
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[k]||icons.bowl}</svg>`;
let mode=launchMode();
let foodView='all',ownerCategory='all',currentEdit=null,editSaving=false,bannerSaving=false,livePollTimer=null,liveRefreshing=false,loadRevision=0;
let repo,state,cart=[],category='all',search='',filter='active',ownerSearch='',catalogSearch='',busy=false,toastTimer,currentDish=null,dishQty=1,draftPhoto=null,draftPreview=null,liveError=null;
let practice=new PracticeRepository(CATALOG);const photoUrls=new Map();let customerId;
try{customerId=localStorage.getItem('jele:customer-id')||crypto.randomUUID();localStorage.setItem('jele:customer-id',customerId);}catch{customerId=crypto.randomUUID();}
const cartKey=()=>`jele:${mode}:cart`;
function readCart(){try{const data=JSON.parse(localStorage.getItem(cartKey())||'[]');cart=Array.isArray(data)?data.filter(l=>l&&typeof l.dishId==='string'&&Array.isArray(l.selected)&&Number.isInteger(l.qty)&&l.qty>0&&l.qty<=99).map(l=>({dishId:l.dishId,selected:l.selected.filter(x=>typeof x==='string'),qty:l.qty,note:String(l.note||'').slice(0,200),spice:String(l.spice||'').slice(0,40)})):[];}catch{cart=[];}}
function saveCart({clearRequest=true}={}){try{localStorage.setItem(cartKey(),JSON.stringify(cart));if(clearRequest)localStorage.removeItem('jele:'+mode+':request');}catch{toast('เก็บตะกร้าในเครื่องไม่ได้');}}
function route(){try{return(location.hash.replace(/^#\/?/,'')||'menu').split('/').map(decodeURIComponent);}catch{return['menu'];}}
const isMother=()=>route()[0]==='mother';
const path=(name,id)=>'#/mother/'+name+(id?'/'+encodeURIComponent(id):'');
function go(hash){if(location.hash===hash){render();return;}location.hash=hash;}
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function hydrate(){document.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
function sheet(title,content,{sub='',footer=''}={}){$('#sheetContent').innerHTML=`<div class="sheet-head"><div>${sub?`<p>${esc(sub)}</p>`:''}<h2 id="sheetTitle">${esc(title)}</h2></div><button class="close" data-action="close" aria-label="ปิด">${icon('close')}</button></div>${content}${footer?`<div class="sheet-foot">${footer}</div>`:''}`;$('#sheet').setAttribute('aria-labelledby','sheetTitle');if(!$('#sheet').open)$('#sheet').showModal();hydrate();}
function closeSheet(){$('#sheet').close();}
$('#sheet').addEventListener('close',()=>{if(draftPreview)URL.revokeObjectURL(draftPreview);draftPhoto=null;draftPreview=null;});
$('#sheet').addEventListener('click',e=>{if(e.target===$('#sheet')){const b=e.target.getBoundingClientRect();if(e.clientX<b.left||e.clientX>b.right||e.clientY<b.top||e.clientY>b.bottom)closeSheet();}});
async function photos(){const keys=[...state.menu.map(d=>d.photoKey),state.settings.bannerPhotoKey].filter(Boolean);if(mode==='live'&&repo.preloadPhotos)await repo.preloadPhotos(keys);for(const key of new Set(keys)){if(mode==='live'||!photoUrls.has(key)){const u=await repo.photo(key);if(u)photoUrls.set(key,u);else if(mode==='live')photoUrls.delete(key);}}}
function shopBanner(){return bannerMarkup({owner:isMother(),src:photoUrls.get(state?.settings?.bannerPhotoKey)||undefined});}
async function reload({renderPage=true}={}){
  const revision=++loadRevision,requestedMode=mode,requestedRepo=repo,owner=isMother();
  const loaded=requestedMode==='practice'?await requestedRepo.load():await requestedRepo.load({owner});
  if(revision!==loadRevision||mode!==requestedMode||repo!==requestedRepo)return false;
  state=loaded;
  await photos();
  if(revision!==loadRevision||mode!==requestedMode||repo!==requestedRepo)return false;
  ensureLivePolling();
  if(renderPage)render();
  return true;
}
async function mutate(action,payload={}){if(busy)return;busy=true;try{if(mode==='live'){await repo.execute(action,payload,state);await reload({renderPage:false});}else{state=await repo.update(old=>{switch(action){case'open':return openShop(old);case'pause':{const s=clone(old);s.settings.open=false;return s;}case'advance':return advanceOrder(old,payload.id);case'pay':return payOrder(old,payload.id,{finish:payload.finish!==false,method:payload.method||'cash'});case'cancel':return cancelOrder(old,payload.id,payload.reason);case'refund':return refundOrder(old,payload.id);case'close':return closeDay(old);case'stock':return changeStock(old,payload.key,payload.available);case'dish':return updateDish(old,payload.id,payload.patch);case'shop-banner':{const s=clone(old);s.settings.bannerPhotoKey=payload.photoKey;return s;}case'add-dish':return addDish(old,payload.patch);case'publish':return publishDish(old,payload.id);case'unpublish':return unpublishDish(old,payload.id);default:throw Error('ไม่พบงานนี้');}});await photos();}return true;}catch(e){toast(friendly(e));return false;}finally{busy=false;render();}}
function friendly(e){const m=String(e?.message||e);if(/Failed to fetch|NetworkError|fetch failed|Network request/i.test(m))return 'ยังบันทึกไม่สำเร็จ ตรวจอินเทอร์เน็ตแล้วลองอีกครั้ง';if(/JWT|session|token/i.test(m))return 'หมดเวลาเข้าใช้งาน กรุณาเข้าสู่งานร้านอีกครั้ง';return m.length<200?m:'ทำรายการไม่สำเร็จ กรุณาลองใหม่อีกครั้ง';}
function isAuthFailure(error){return error?.status===401||error?.code==='PGRST301'||/JWT expired|กรุณาเข้าสู่งานร้าน|ไม่มีสิทธิ์ดูแลงานร้านเจ๊เล่/.test(String(error?.message||''));}
function showLiveFailure(error){
  $('#modeBand').textContent=liveConfigured()?'ร้านเจ๊เล่ · ยังเชื่อมต่อไม่ได้':'ร้านเจ๊เล่ · ยังไม่เปิดรับรายการ';
  $('#bottomArea').innerHTML='';
  if(liveConfigured()&&isMother()&&isAuthFailure(error)){showLogin(friendly(error));return;}
  const configured=liveConfigured();
  $('#app').innerHTML='<div class="error-view"><h1>'+(configured?'ยังเปิดข้อมูลร้านไม่ได้':'ร้านกำลังเตรียมเปิด')+'</h1><p>'+(configured?esc(friendly(error)):'เจ้าของร้านกำลังจัดเตรียมข้อมูลร้านเจ๊เล่ให้พร้อมค่ะ')+'</p>'+(configured?'<button class="primary" data-action="retry-load">ลองเปิดอีกครั้ง</button>':'')+'</div>';
}
function ensureLivePolling(){
  if(mode!=='live'){if(livePollTimer)clearInterval(livePollTimer);livePollTimer=null;return;}
  if(livePollTimer||!liveConfigured())return;
  livePollTimer=setInterval(async()=>{
    if(mode!=='live'||busy||editSaving||bannerSaving||liveRefreshing||$('#sheet').open||document.visibilityState!=='visible')return;
    liveRefreshing=true;
    try{await reload();}catch(error){if(isAuthFailure(error)&&isMother()){clearInterval(livePollTimer);livePollTimer=null;showLogin(friendly(error));}else toast(friendly(error));}finally{liveRefreshing=false;}
  },15000);
}

function intro(title,sub='',eyebrow='ครัวเจ๊เล่'){return `<div class="page-intro"><div><p class="eyebrow">${esc(eyebrow)}</p><h1>${esc(title)}</h1>${sub?`<p class="muted">${esc(sub)}</p>`:''}</div><span class="status-pill ${state.settings.open?'':'closed'}">${state.settings.open?'เปิดรับรายการ':'ยังไม่เปิดรับ'}</span></div>`;}
const empty=(title,text,button='')=>`<div class="empty">${icon('bowl')}<h3>${esc(title)}</h3><p>${esc(text)}</p>${button}</div>`;
function dishPrice(d){const ps=displayPrices(state,d);if(!ps.length)return'<span class="dish-price pending">รอกำหนดราคา</span>';return `<span class="dish-price">${ps.length>1&&Math.min(...ps)!==Math.max(...ps)?'เริ่ม ':''}${money(Math.min(...ps))}</span>`;}
function dishCard(d){
  const image=photoUrls.get(d.photoKey),sold=d.available===false||!isAllStock(d),theme=THEMES[d.category]||THEMES.made;
  return `<article class="dish-card ${image?'has-photo':''} ${sold?'sold':''}" data-food="${esc(d.category)}">${d.recommended?'<span class="recommend-stamp">★ จานแนะนำ</span>':''}${image?`<img class="dish-photo" src="${esc(image)}" alt="${esc(d.name)}" loading="lazy">`:`<div class="dish-art-stage">${foodArt(d.category,'card-'+d.id)}<span class="food-label">${esc(theme.name)}</span></div>`}<div class="dish-card-body"><h4>${esc(d.name)}</h4><p class="dish-desc">${esc(d.recipe||d.description||theme.note)}</p><div class="dish-foot">${sold?'<span class="badge red">หมดชั่วคราว</span>':dishPrice(d)}<button class="dish-select" data-action="dish" data-id="${esc(d.id)}" aria-label="เลือก${esc(d.name)}">${icon('plus')}</button></div></div></article>`;
}
function isAllStock(d){return (d.stockKeys||[]).every(k=>state.stock[k]!==false);}
function foodCategories(){
  const item=(action,value,label,on)=>'<button class="reference-category '+(on?'selected':'')+'" data-action="'+action+'" data-value="'+value+'" aria-pressed="'+on+'">'+esc(label)+'</button>';
  return '<div class="reference-categories" role="group" aria-label="หมวดอาหาร">'+item('category','all','ทั้งหมด',category==='all'&&foodView==='all')+item('food-view','recommended','★ แนะนำ',foodView==='recommended')+Object.entries(THEMES).map(([id,t])=>item('category',id,t.name,category===id&&foodView==='all')).join('')+item('food-view','special','เมนูพิเศษ',foodView==='special')+'</div>';
}

function renderMenu(){
  const term=search.trim().toLocaleLowerCase('th');
  const list=visibleMenu(state).filter(d=>(category==='all'||d.category===category)&&(!term||d.name.toLocaleLowerCase('th').includes(term))&&(foodView==='all'||(foodView==='recommended'?d.recommended:d.special)));
  list.sort((a,b)=>Number(b.recommended)-Number(a.recommended));
  const featured=visibleMenu(state).find(d=>d.name==='ยำวุ้นเส้น');
  const title=foodView==='recommended'?'จานแนะนำของแม่':foodView==='special'?'จานพิเศษ':category==='all'?'เมนูบ้านเรา':THEMES[category].name;
  return shopBanner()+intro('เมนูอาหาร','เลือกเมนูแล้วกดเพิ่มลงตะกร้า','เจ๊เล่ส้มตำ').replace('class="page-intro"','class="page-intro shop-intro"')+`<div class="shop-layout"><section class="shop-main"><div class="feature-dish"><div class="hero-copy"><p class="eyebrow">เจ๊เล่ส้มตำ · ครัวบ้านเรา</p><h2>อิ่มจานร้อน<br>แซ่บถึงครก</h2><p>${featured?'ยำวุ้นเส้นจานเด่นของแม่<span class="hero-subline"><br>เลือกความเผ็ดได้ตามใจ</span>':'เลือกจานอิ่ม คู่กับครกโปรด<br>ให้ครบมื้อในบ้านเรา'}</p>${featured?`<button class="feature-cta" data-action="dish" data-id="${esc(featured.id)}">เลือกจานเด่น ${icon('arrow')}</button>`:''}</div><div class="hero-scene"><div class="hero-halo"></div>${foodArt('yum','hero-yum')}${foodArt('som','hero-som').replace('class="food-art"','class="food-art hero-mortar"')}<span class="hero-tag">รสมือแม่</span></div></div>${foodCategories()}<section class="menu-tools" aria-label="ค้นหาและเลือกชุดเมนู"><label class="search">${icon('search')}<input type="search" id="menuSearch" value="${esc(search)}" placeholder="ค้นหาอาหารที่อยากทาน" aria-label="ค้นหาอาหาร"></label></section><div class="menu-title-line"><h3>${esc(title)}</h3><small>${list.length} รายการ</small></div>${list.length?`<div class="menu-grid">${list.map(dishCard).join('')}</div>`:empty(visibleMenu(state).length?'ยังไม่พบจานนี้':'ร้านกำลังจัดเมนู',visibleMenu(state).length?'ลองค้นสั้นลง หรือเปลี่ยนหมวดอาหารค่ะ':'รายชื่ออาหารอยู่ระหว่างเตรียมเปิดขายค่ะ')}</section><aside class="shop-aside"><div class="kitchen-note">${icon('home')}<h3>กินข้าวบ้านเรา</h3><p>จานร้อนจากกระทะ<br>ยำจัดจ้านกับส้มตำครกโปรด<br>ฝากข้อความให้ตรงกับจานที่ชอบ</p><span class="status-pill ${state.settings.open?'':'closed'}">${state.settings.open?'แม่เปิดร้านแล้ว':'แม่ยังไม่เปิดรับรายการ'}</span></div><button class="side-link" data-action="orders">รายการที่ฉันสั่ง ${icon('receipt')}</button><a class="side-link" href="#/mother">งานของแม่ ${icon('arrow')}</a><a class="side-link" href="#/help">วิธีใช้งาน ${icon('help')}</a></aside></div>`;
}
function currentLines(){return cart.map(l=>{try{return {input:l,line:lineFor(state,l.dishId,l)};}catch(e){return{input:l,error:friendly(e),dish:state.menu.find(d=>d.id===l.dishId)};}});}
function motherAside(){return `<aside class="mother-aside"><h3>ทำตามงานที่ทำอยู่</h3><p>แม่ดูรายการ แล้วกดทีละขั้น<br>ปุ่มอยู่ที่เดิมทุกวัน</p><div class="step"><b>1</b><span>อ่านอาหารและหมายเหตุ<br>กด <strong>เริ่มทำ</strong></span></div><div class="step"><b>2</b><span>อาหารครบแล้ว<br>กด <strong>ทำเสร็จแล้ว</strong></span></div><div class="step"><b>3</b><span>รับเงินจริงแล้ว<br>กด <strong>รับเงินแล้ว</strong></span></div><a class="side-link" href="#/help">ดูวิธีใช้ทีละขั้น ${icon('arrow')}</a><a class="side-link" href="#/menu">เปิดหน้าลูกค้า ${icon('arrow')}</a></aside>`;}
function orderLines(o){return o.lines.map(l=>`<div class="order-line"><div><h4>${esc(l.name)} <span class="muted">${l.qty} ${l.qty>1?'จาน':'จาน'}</span></h4>${l.optionNames?.length?`<p>${l.optionNames.map(esc).join(' · ')}</p>`:''}${l.spice?`<p>${esc(l.spice)}</p>`:''}${l.note?`<p class="note">ฝากบอกแม่: ${esc(l.note)}</p>`:''}</div>${Number.isInteger(l.total)?`<strong>${money(l.total)}</strong>`:''}</div>`).join('');}
function orderCard(o,{customer=false}={}){let action='';if(!customer){if(o.status==='new')action=`<button class="primary" data-action="advance" data-id="${esc(o.id)}">เริ่มทำ ${icon('arrow')}</button>`;else if(o.status==='preparing')action=`<button class="primary" data-action="advance" data-id="${esc(o.id)}">ทำเสร็จแล้ว ${icon('check')}</button>`;else if(o.status==='ready')action=`<button class="primary" data-action="${o.paid?'deliver':'pay-sheet'}" data-id="${esc(o.id)}">${o.paid?'ส่งอาหารแล้ว':'รับเงินแล้ว'} ${icon(o.paid?'check':'cash')}</button>`;if(o.status!=='completed'&&o.status!=='cancelled')action+=`<button class="text-button" data-action="order-more" data-id="${esc(o.id)}">เพิ่มเติม</button>`;if(o.refund?.status==='required')action=`<button class="danger" data-action="refund-sheet" data-id="${esc(o.id)}">บันทึกคืนเงินแล้ว</button>`;}
return `<article class="order-card" data-status="${esc(o.status)}"><div class="order-head"><div><span class="queue-code">${esc(o.code)}</span><small>${time(o.createdAt)} · ${o.fulfillment==='dine_in'?'ทานที่ร้าน':'กลับบ้าน'}</small></div><span class="order-status ${o.status}">${STATUS[o.status]||esc(o.status)}</span></div>${orderLines(o)}${o.cancelReason?`<p class="small muted">เหตุผล: ${esc(o.cancelReason)}</p>`:''}<div class="order-total"><span>${o.refund?.status==='required'?'ต้องคืนเงิน':o.refund?.status==='completed'?'คืนเงินแล้ว':o.paid?'รับเงินแล้ว':'ยังไม่ได้รับเงิน'}</span><b>${money(o.total)}</b></div>${action?`<div class="order-buttons">${action}</div>`:''}${customer?`<button class="text-button" data-action="track" data-id="${esc(o.id)}">ดูสถานะรายการ</button>`:''}</article>`;}
function getSummary(){return state.liveSummary||totals(state);}
function renderMother(){const s=getSummary();const pending=state.orders.filter(o=>!['completed','cancelled'].includes(o.status));const orders=filter==='active'?pending:state.orders.filter(o=>filter==='all'||o.status===filter);orders.sort((a,b)=>new Date(a.createdAt)-new Date(b.createdAt));return `<div class="mother-layout"><section class="mother-main"><div class="mother-toolbar"><div><p class="eyebrow">งานของแม่ · ${day(bangkokDate())}</p><h2>งานวันนี้</h2></div><button class="${state.settings.open?'secondary':'primary'}" data-action="${state.settings.open?'pause':'open'}">${state.settings.open?'พักรับรายการใหม่':'เปิดร้าน'}</button></div>${!state.settings.open?`<div class="notice ${state.menu.some(d=>menuReady(state,d))?'':'warning'}"><strong>ยังไม่เปิดรับรายการ</strong><br>${state.menu.some(d=>menuReady(state,d))?'พร้อมเมื่อไหร่ กดเปิดร้านด้านบนได้เลยค่ะ':'ไปจัดรายชื่อ ตั้งราคา และกดเปิดขายอย่างน้อย 1 เมนูก่อนค่ะ'} <a class="text-button" href="#/mother/pending">จัดเมนูวันนี้</a></div>`:''}<div class="metrics"><div class="metric">${icon('receipt')}<b>${s.newCount??pending.filter(o=>o.status==='new').length}</b><span>รายการใหม่</span></div><div class="metric">${icon('fire')}<b>${s.preparingCount??pending.filter(o=>o.status==='preparing').length}</b><span>กำลังทำ</span></div><div class="metric">${icon('check')}<b>${s.readyCount??pending.filter(o=>o.status==='ready').length}</b><span>พร้อมรับ</span></div></div><div class="tabs" role="group" aria-label="กรองรายการ">${[['active','งานค้าง'],['all','ทั้งหมด'],['completed','เสร็จแล้ว'],['cancelled','ยกเลิก']].map(([id,name])=>`<button class="chip ${filter===id?'selected':''}" data-action="order-filter" data-value="${id}" aria-pressed="${filter===id}">${name}</button>`).join('')}</div>${orders.length?orders.map(o=>orderCard(o)).join(''):empty('ยังไม่มีรายการ'+(filter==='active'?'ค้าง':''),state.settings.open?'เปิดหน้าลูกค้าเพื่อเริ่มฝึกสั่งอาหารได้ค่ะ':'ตั้งราคาและเปิดร้าน แล้วค่อยเริ่มรับรายการค่ะ',`<a class="primary" href="#/menu">ไปหน้าลูกค้า ${icon('arrow')}</a>`)}${mode==='practice'?'<p class="small muted">รายการฝึกในเครื่องเดียวกันแสดงทั้งหน้าลูกค้าและหน้างานแม่ เปิดคนละแท็บเพื่อฝึกพร้อมกันได้</p>':''}</section>${motherAside()}</div>`;}
function savedPrices(d){
  return d.priceMode==='choice'?groupsFor(d)[0]?.values.filter(v=>Number.isInteger(v.price)&&v.price>0).map(v=>({name:v.name,price:v.price}))||[]:Number.isInteger(d.price)&&d.price>0?[{name:'',price:d.price}]:[];
}
function ownerMenuRow(d,published){
  const prices=savedPrices(d),image=photoUrls.get(d.photoKey),configured=dishConfigured(state,d);
  return `<article class="draft-row" data-id="${esc(d.id)}" data-food="${esc(d.category)}"><div class="draft-main">${image?`<img class="draft-thumb" src="${esc(image)}" alt="${esc(d.name)}">`:`<span class="draft-thumb no-photo">${icon('image')}</span>`}<div class="draft-copy"><h4>${esc(d.name)}</h4><p class="saved-price">${prices.length?prices.map(v=>`${v.name?esc(v.name)+' ':''}${money(v.price)}`).join(' · '):'ยังไม่ได้ตั้งราคา'}</p><div class="draft-tags">${!prices.length?'<span class="badge warn">รอราคา</span>':''}${!image?'<span class="badge">รอภาพ</span>':''}${d.recipeRequired&&(!d.recipe?.trim()||!d.stockKeys?.length)?'<span class="badge warn">รอของในจาน</span>':''}${published?'<span class="badge sale">เปิดขายแล้ว</span>':configured?'<span class="badge ready">ตั้งราคาแล้ว · ยังไม่เปิดขาย</span>':''}</div></div></div><div class="draft-actions"><button class="secondary" data-action="edit" data-id="${esc(d.id)}" aria-label="แก้${esc(d.name)}">แก้ชื่อ / ราคา</button>${published?`<button class="text-button" data-action="unpublish-sheet" data-id="${esc(d.id)}">เก็บไว้รอเปิดขาย</button>`:`<button class="primary" data-action="publish-sheet" data-id="${esc(d.id)}" ${configured?'':'disabled'}>เปิดขาย</button>`}</div></article>`;
}
function renderMotherMenu(){
  const publishedPane=route()[1]==='published',included=state.menu.filter(d=>d.active!==false),pending=included.filter(d=>!d.published),published=included.filter(d=>d.published);
  const allItems=publishedPane?published:pending;
  const items=allItems.filter(d=>(ownerCategory==='all'||d.category===ownerCategory)&&(!ownerSearch.trim()||d.name.includes(ownerSearch.trim())));
  const categories=['yum','som','made','side'];
  const withPhotos=included.filter(d=>photoUrls.has(d.photoKey)).length,photoPercent=included.length?Math.round(withPhotos*100/included.length):0;
  const photoProgress=`<section class="menu-photo-progress" aria-label="จำนวนรูปเมนู"><div><strong>รูปเมนู ${withPhotos} / ${included.length}</strong><span>${photoPercent}%</span></div><progress max="${included.length||1}" value="${withPhotos}" aria-label="รูปเมนูที่บันทึกแล้ว">${photoPercent}%</progress></section>`;
  return shopBanner()+photoProgress+`<div class="mother-layout"><section class="mother-main"><div class="mother-toolbar"><div><p class="eyebrow">เมนูของแม่ · แก้ไขและเก็บไว้ได้</p><h2>${publishedPane?'เมนูที่เปิดขาย':'รอเปิดขาย'}</h2></div><button class="primary add-menu-button" data-action="new-dish">${icon('plus')} เพิ่มเมนู</button></div><nav class="menu-panes" aria-label="สถานะเมนู"><a class="${publishedPane?'':'active'}" href="#/mother/pending">รอเปิดขาย <b>${pending.length}</b></a><a class="${publishedPane?'active':''}" href="#/mother/published">เปิดขายแล้ว <b>${published.length}</b></a></nav>${!publishedPane?`<div class="draft-intro"><p>ชื่อและราคาแก้ทีหลังได้<br>ภาพค่อยใส่ เมนูยังอยู่รอเปิดขาย</p><button class="text-button" data-action="catalog">รายชื่อเพิ่มเติม</button></div>`:''}<div class="owner-categories" role="group" aria-label="หมวดเมนูของแม่">${[['all','ทั้งหมด'],...categories.map(id=>[id,THEMES[id].name])].map(([id,name])=>`<button data-action="owner-category" data-value="${id}" aria-pressed="${ownerCategory===id}">${name}</button>`).join('')}</div><details class="draft-search" ${ownerSearch.trim()?'open':''}><summary>${icon('search')} ค้นหารายชื่อ</summary><label class="search"><input type="search" id="ownerSearch" value="${esc(ownerSearch)}" placeholder="ค้นหาชื่อเมนู" aria-label="ค้นหาเมนูของแม่"></label></details><div class="draft-groups">${categories.filter(id=>ownerCategory==='all'||ownerCategory===id).map(id=>{const group=items.filter(d=>d.category===id),theme=THEMES[id];if(publishedPane&&!group.length)return '';return `<section class="draft-group" data-food="${id}" aria-label="${esc(theme.name)}${publishedPane?'ที่เปิดขาย':'รอเปิดขาย'}"><div class="draft-group-head"><div><h3>${esc(theme.name)}</h3><span>${group.length} เมนู</span></div><button class="add-to-group" data-action="new-dish" data-category="${id}">${icon('plus')} เพิ่ม${esc(theme.short)}</button></div>${group.length?group.map(d=>ownerMenuRow(d,publishedPane)).join(''):`<p class="draft-empty">${ownerSearch?'ไม่พบชื่อนี้ในหมวดนี้':publishedPane?'ยังไม่มีเมนูเปิดขาย':'กดเพิ่มเพื่อเก็บรายชื่อในหมวดนี้'}</p>`}</section>`;}).join('')}${publishedPane&&!items.length?empty('ยังไม่มีเมนูเปิดขาย','เลือกเมนูจากหน้ารอเปิดขายเมื่อพร้อมค่ะ','<a class="primary" href="#/mother/pending">ไปหน้ารอเปิดขาย</a>'):''}</div>${publishedPane&&mode==='practice'?`<details class="stock-details"><summary>ของที่มีขายวันนี้</summary><div class="stock-grid">${STOCK.map(([key,name])=>`<div class="stock-item"><div>${name}<small>${state.stock[key]!==false?'มีขาย':'หมดวันนี้'}</small></div><button class="switch ${state.stock[key]!==false?'on':''}" role="switch" aria-checked="${state.stock[key]!==false}" aria-label="${esc(name)} ${state.stock[key]!==false?'มีขาย':'หมดวันนี้'}" data-action="stock" data-key="${key}"></button></div>`).join('')}</div></details>`:''}</section><aside class="mother-aside"><h3>เพิ่มเมนูตามที่แม่ขาย</h3><div class="step"><b>1</b><span>กดเพิ่มเมนู<br>ตั้งชื่อและเลือกหมวด</span></div><div class="step"><b>2</b><span>ใส่ราคาเมื่อพร้อม<br>ภาพค่อยใส่ทีหลังได้</span></div><div class="step"><b>3</b><span>บันทึกรอเปิดขาย<br>กดเปิดขายเมื่ออยากให้สั่งได้</span></div><a class="side-link" href="#/help">วิธีใช้งาน ${icon('help')}</a></aside></div>`;
}
function renderSummary(){
  const s=getSummary(),pending=state.orders.filter(o=>!['completed','cancelled'].includes(o.status));
  return `<div class="mother-layout"><section class="mother-main">${intro('ยอดวันนี้','นับจากรายการที่รับเงินจริงแล้ว','งานของแม่ · '+day(bangkokDate()))}<div class="summary-grid"><div class="summary-box major">${icon('cash')}<h3>รับเงินสุทธิวันนี้</h3><b>${money(s.net)}</b><div class="summary-receipt-foot"><span>รับเงินแล้ว หักเงินที่คืนแล้ว</span><span class="receipt-stamp">${icon('check')} ${mode==='practice'?'ยอดฝึกในเครื่อง':'ยอดของร้าน'}</span></div></div><div class="summary-box received">${icon('receipt')}<h3>รับเงินแล้ว</h3><b>${money(s.received)}</b></div><div class="summary-box refunded">${icon('undo')}<h3>คืนเงินแล้ว</h3><b>${money(s.refunded)}</b></div><div class="summary-box pending">${icon('list')}<h3>รายการค้าง</h3><b>${s.pendingCount} รายการ</b></div><div class="summary-box unpaid">${icon('clock')}<h3>ยังไม่ได้รับเงิน</h3><b>${money(s.unpaid)}</b></div></div>${s.refundDue?`<div class="notice error">ยังมีเงินที่ต้องคืน ${money(s.refundDue)}<br>เปิดรายการยกเลิกเพื่อตรวจและบันทึกคืนเงินจริง</div>`:''}<div class="guide closing-guide"><h3>ก่อนจบวันนี้</h3><p>${pending.length?'ยังมีงานค้าง '+pending.length+' รายการ ตรวจให้ครบก่อนค่ะ':'ไม่มีรายการค้างแล้ว ตรวจยอดเงินก่อนจบวันได้ค่ะ'}</p><div class="actions"><button class="secondary" data-action="pause">ปิดรับรายการใหม่</button><button class="primary" data-action="close-day">จบวัน ${icon('check')}</button></div></div>${state.closings.length?`<div class="section-label"><h2>วันที่เก็บยอดแล้ว</h2></div>${[...state.closings].sort((a,b)=>b.day.localeCompare(a.day)).map(c=>`<div class="closing-row"><span>${day(c.day)}</span><b>${money(c.net??c.received)}</b></div>`).join('')}`:''}</section>${motherAside()}</div>`;
}
function renderHelp(){return intro('ใช้ทีละขั้น ตามงานของแม่','เริ่มจากอาหารหนึ่งจาน แล้วค่อยลองสถานการณ์อื่น','วิธีใช้')+`<div class="help-layout"><section><article class="guide"><h3>ก่อนเริ่มครั้งแรก</h3><div class="guide-step"><span>1</span><div><h4>เพิ่มชื่อและเลือกหมวดอาหาร</h4><p>ไปเมนู → รอเปิดขาย → เพิ่มเมนู ตั้งชื่อ เลือกหมวด แล้วบันทึก แก้ชื่อ ย้ายหมวด ใส่ราคา หรือใส่ภาพทีหลังได้</p></div></div><div class="guide-step"><span>2</span><div><h4>กดเปิดร้าน</h4><p>เมื่อจานที่อยากลองมีราคาแล้ว กดเปิดขายจากหน้ารอ จากนั้นไปงานวันนี้ กดเปิดร้าน แล้วฝึกสั่งจากหน้าลูกค้า</p></div></div><div class="guide-step"><span>3</span><div><h4>กลับมาทำรายการของแม่</h4><p>แม่อ่านอาหาร เนื้อ จำนวน และข้อความที่ฝากไว้ แล้วกดทีละขั้น</p></div></div><div class="guide-buttons"><div>เริ่มทำ</div><div>ทำเสร็จแล้ว</div><div>รับเงินแล้ว</div></div><p class="small">กดรับเงินหลังได้รับเงินจริง ถ้าฝึกอยู่ รายการและยอดเงินเป็นข้อมูลฝึกในเครื่องนี้ค่ะ</p><a class="primary" href="#/mother/pending">เริ่มตั้งเมนู ${icon('arrow')}</a></article><article class="guide"><h3>เปลี่ยนภาพและของในจาน</h3><p>หน้าเมนู → แก้ไข → เลือกภาพ → ดูภาพก่อนใช้ → บันทึก แม่เอารูปออกหรือเปลี่ยนใหม่ได้ ชื่ออาหารกับราคายังอ่านได้แม้ยังไม่มีรูป</p><p>จานรวมให้แม่บอกของที่รวมและเลือกวัตถุดิบที่ใช้ เพื่อให้ปิดของหมดได้ตรงจาน</p></article><article class="guide"><h3>ลองให้ครบก่อนใช้ประจำ</h3><div class="guide-step"><span>1</span><div><h4>สั่งหนึ่งจาน แล้วสั่งหลายจาน</h4><p>ดูว่าจำนวน ตัวเลือก ความเผ็ด และข้อความตรงกันทั้งสองหน้า</p></div></div><div class="guide-step"><span>2</span><div><h4>ลองของหมดและยกเลิก</h4><p>ปิดกุ้งแล้วตรวจจานที่ใช้กุ้ง รายการที่ส่งมาแล้วไม่หาย ยกเลิกต้องมีเหตุผล</p></div></div><div class="guide-step"><span>3</span><div><h4>ลองรับเงินซ้ำและปิดวัน</h4><p>ยอดรับเงินไม่เพิ่มซ้ำ รายการค้างยังเห็นอยู่ และจบวันเมื่อเคลียร์งานครบแล้ว</p></div></div></article><article class="guide"><h3>พื้นที่ของร้าน</h3><p>${mode==='practice'?'ตอนนี้กำลังฝึกในเครื่องนี้ ข้อมูลไม่ส่งเข้าร้านจริงและไม่ปนกับร้านคุณยุ้ย':'ตอนนี้เชื่อมข้อมูลร้านเจ๊เล่กับระบบกลาง การเปลี่ยนแปลงมีผลกับร้านจริง'}</p>${mode==='practice'?`<button class="secondary" data-action="live-info">ดูสถานะการเชื่อมร้านจริง</button> <button class="text-button" data-action="reset-practice">เริ่มข้อมูลฝึกใหม่</button>`:`<button class="secondary" data-action="practice-mode">กลับพื้นที่ฝึก</button> <button class="text-button" data-action="logout">ออกจากงานร้าน</button>`}</article></section><aside class="mother-aside"><h3>ลองด้วยราคาที่แม่กรอก</h3><p>ไม่มีราคาตั้งให้ล่วงหน้า แม่เลือกตั้งเฉพาะจานที่อยากลองก่อน แล้วค่อยเพิ่มจานอื่นค่ะ</p><a class="side-link" href="#/menu">ไปหน้าลูกค้า ${icon('arrow')}</a><a class="side-link" href="#/mother">ไปงานวันนี้ ${icon('arrow')}</a><a class="side-link" href="../#/exec">ระบบกลางของคุณ ${icon('arrow')}</a></aside></div>`;}
function customerOrders(){const orders=state.orders.filter(o=>mode==='live'||o.customerId===customerId).sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));return intro('รายการที่ฉันสั่ง','ตรวจชื่ออาหารและดูสถานะรับอาหาร')+(orders.length?`<div class="narrow">${orders.map(o=>orderCard(o,{customer:true})).join('')}</div>`:empty('ยังไม่มีรายการ','เลือกอาหารแล้วตรวจตะกร้าก่อนส่งค่ะ','<a class="primary" href="#/menu">เลือกเมนู</a>'));}
function tracking(id){const o=state.orders.find(o=>o.id===id&&(mode==='live'||o.customerId===customerId));if(!o)return empty('ยังไม่พบรายการนี้','เปิดรายการที่ฉันสั่งเพื่อตรวจอีกครั้งค่ะ','<a class="primary" href="#/orders">ดูรายการที่ฉันสั่ง</a>');const statuses=['new','preparing','ready','completed'];return `<div class="narrow"><a class="back-link" href="#/orders">${icon('back')} รายการที่ฉันสั่ง</a><div class="back-order"><p class="eyebrow">${mode==='practice'?'รายการฝึก':'รายการของคุณ'}</p><div class="big-code">${esc(o.code)}</div><span class="order-status ${o.status}">${STATUS[o.status]}</span>${o.status==='cancelled'?`<p class="muted" style="margin-top:20px">${esc(o.cancelReason||'ร้านยกเลิกรายการนี้')}</p>`:`<div class="timeline">${statuses.map((st,i)=>`<div class="station ${statuses.indexOf(o.status)>=i?'active':''}"><span>${statuses.indexOf(o.status)>i?icon('check'):i+1}</span><div>${['รับรายการแล้ว','แม่กำลังทำ','พร้อมรับอาหาร','ส่งอาหารและจบรายการแล้ว'][i]}</div></div>`).join('')}</div>`}</div><div class="order-card">${orderLines(o)}<div class="order-total"><span>${o.paid?'รับเงินแล้ว':'ชำระที่ร้าน'}</span><b>${money(o.total)}</b></div></div><p class="small muted">แจ้งรหัสรายการกับแม่ และตรวจอาหารก่อนรับกลับค่ะ</p><a class="primary wide" href="#/menu">กลับไปเลือกอาหาร</a></div>`;}
function bottom(){if(isMother()){const r=['pending','published'].includes(route()[1])?'menu':route()[1]||'orders';return `<nav class="bottom-nav" aria-label="งานของแม่">${[['menu','หน้าหลักและเมนู','home'],['orders','ออเดอร์','list'],['summary','ยอดวันนี้','cash']].map(([id,name,ic])=>`<a class="${r===id?'active':''}" href="${id==='orders'?'#/mother':id==='menu'?'#/mother/pending':path(id)}">${icon(ic)}${name}</a>`).join('')}</nav>`;}if(route()[0]==='help')return '';if(cart.length){const lines=currentLines(),valid=lines.every(x=>x.line),total=lines.reduce((s,x)=>s+(x.line?.total||0),0);return `<div class="cart-dock"><button data-action="cart"><span>ดูตะกร้า <small>${cart.reduce((a,l)=>a+l.qty,0)} จาน</small></span><b>${valid?money(total):'ตรวจรายการ'}</b>${icon('arrow')}</button></div>`;}return'';}
function render(){if(!state)return;document.body.dataset.shopView=isMother()?'mother':'customer';const r=route();let html;if(r[0]==='mother')html=(['menu','pending','published'].includes(r[1])?renderMotherMenu():r[1]==='summary'?renderSummary():renderMother());else if(r[0]==='help')html=renderHelp();else if(r[0]==='orders')html=customerOrders();else if(r[0]==='track')html=tracking(r[1]);else html=renderMenu();$('#app').innerHTML=html;$('#bottomArea').innerHTML=bottom();$('#cartCount').textContent=cart.reduce((a,l)=>a+l.qty,0);$('#modeBand').textContent=mode==='practice'?'พื้นที่ฝึกใช้งาน · รายการและเงินไม่เข้าร้านจริง':'ร้านเจ๊เล่ · เชื่อมระบบกลางแล้ว';document.querySelectorAll('[data-role-tab]').forEach(a=>a.classList.toggle('active',a.dataset.roleTab===(isMother()?'mother':r[0]==='help'?'help':'customer')));hydrate();}
function showDish(id){const d=visibleMenu(state).find(x=>x.id===id);if(!d)return;currentDish=d;dishQty=1;const groups=groupsFor(d);const image=photoUrls.get(d.photoKey);sheet(d.name,`<form id="dishForm"><div class="sheet-body">${image?`<img class="dish-sheet-image" src="${esc(image)}" alt="${esc(d.name)}">`:''}${d.recipe||d.description?`<p class="muted small">${esc(d.recipe||d.description)}</p>`:''}${!menuReady(state,d)?`<div class="notice warning">${d.available===false||!isAllStock(d)?'เมนูนี้หมดชั่วคราวค่ะ':'เมนูนี้ยังไม่พร้อมรับรายการ รอแม่กำหนดราคาและของที่ขายค่ะ'}</div>`:''}${groups.map((g,gi)=>`<fieldset class="option-group"><legend>${esc(g.name)} <small>${g.min||g.required?'ต้องเลือก':'ไม่บังคับ'}${g.max===1?' 1 อย่าง':''}</small></legend><div class="options">${g.values.map(v=>{const available=choiceAvailable(state,v)&&(d.priceMode!=='choice'||gi!==0||Number.isInteger(v.price));return `<label class="option"><span><input type="${g.max===1?'radio':'checkbox'}" name="group-${esc(g.id)}" value="${esc(v.id)}" ${available?'':'disabled'}> ${esc(v.name)}<small>${d.priceMode==='choice'&&gi===0?money(v.price):(v.delta?'เพิ่ม '+money(v.delta):'ไม่คิดเพิ่ม')}${!choiceAvailable(state,v)?' · หมด':''}</small></span></label>`;}).join('')}</div></fieldset>`).join('')}${d.category!=='side'?`<fieldset class="option-group"><legend>ความเผ็ด</legend><div class="options">${['ไม่เผ็ด','เผ็ดน้อย','เผ็ดกลาง','เผ็ดมาก'].map(n=>`<label class="option"><span><input type="radio" name="spice" value="${n}" ${n==='เผ็ดน้อย'?'checked':''}> ${n}</span></label>`).join('')}</div></fieldset>`:''}<label class="field">ฝากบอกแม่ <small>ไม่บังคับ</small><textarea name="note" maxlength="200" placeholder="เช่น ไม่หวาน"></textarea></label><p class="form-error" id="dishError" role="alert"></p></div></form>`,{sub:CATEGORIES.find(([c])=>c===d.category)?.[1],footer:`<div class="quantity"><button data-action="qty-minus" type="button" aria-label="ลดจำนวน">−</button><output id="dishQty">1</output><button data-action="qty-plus" type="button" aria-label="เพิ่มจำนวน">+</button></div><button class="primary" type="submit" form="dishForm" ${menuReady(state,d)?'':'disabled'}>ใส่ตะกร้า <span id="dishTotal">${d.priceMode==='choice'?'เลือกตัวเลือกก่อน':money(d.price)}</span></button>`});}
function selectedDish(){const selected=[...$('#dishForm').querySelectorAll('input[name^="group-"]:checked')].map(x=>x.value);return {dishId:currentDish.id,selected,qty:dishQty,note:$('#dishForm [name="note"]').value,spice:$('#dishForm [name="spice"]:checked')?.value||''};}
function dishTotal(){if(!currentDish||!$('#dishForm'))return;try{const l=lineFor(state,currentDish.id,selectedDish());$('#dishTotal').textContent=money(l.total);}catch{$('#dishTotal').textContent='เลือกตัวเลือกก่อน';}$('#dishQty').textContent=dishQty;}
function showCart(){const rows=currentLines(),valid=rows.every(x=>x.line),total=rows.reduce((a,x)=>a+(x.line?.total||0),0);if(!rows.length)return sheet('ตะกร้าของฉัน',`<div class="sheet-body">${empty('ยังไม่มีอาหารในตะกร้า','เลือกจานที่อยากทานก่อนค่ะ','<button class="primary" data-action="close">ไปเลือกอาหาร</button>')}</div>`);sheet('ตะกร้าของฉัน',`<form id="cartForm"><div class="sheet-body">${rows.map((x,i)=>`<div class="cart-row"><div class="row-top"><h3>${esc(x.line?.name||x.dish?.name||'รายการเดิม')}</h3><b>${x.line?money(x.line.total):'ตรวจรายการ'}</b></div><p>${esc([...(x.line?.optionNames||[]),x.input.spice,x.input.note].filter(Boolean).join(' · '))}</p>${x.error?`<p class="form-error">${esc(x.error)}</p>`:''}<div class="row-bottom"><div class="quantity"><button type="button" data-action="cart-minus" data-index="${i}" aria-label="ลด${esc(x.line?.name||'รายการ')}">−</button><output>${x.input.qty}</output><button type="button" data-action="cart-plus" data-index="${i}" aria-label="เพิ่ม${esc(x.line?.name||'รายการ')}">+</button></div><button type="button" class="text-button" data-action="cart-remove" data-index="${i}">ลบ</button></div></div>`).join('')}<div class="cart-summary"><span>ยอดรวม</span><b>${valid?money(total):'ตรวจรายการก่อน'}</b></div><fieldset class="option-group"><legend>รับอาหารแบบไหน</legend><div class="options"><label class="option"><span><input type="radio" name="fulfillment" value="dine_in" checked> ทานที่ร้าน</span></label><label class="option"><span><input type="radio" name="fulfillment" value="takeaway"> กลับบ้าน</span></label></div></fieldset>${!state.settings.open?'<div class="notice warning">แม่ยังไม่เปิดรับรายการค่ะ</div>':''}<p class="small muted">${mode==='practice'?'รายการนี้เป็นการฝึกในเครื่อง ไม่ส่งเข้าร้านจริง':'ชำระเงินที่ร้าน ตรวจรายการก่อนกดยืนยัน'}</p><p class="form-error" id="cartError" role="alert"></p></div></form>`,{footer:`<button class="primary" type="submit" form="cartForm" ${valid&&state.settings.open?'':'disabled'}>ตรวจรายการก่อนส่ง ${icon('arrow')}</button>`});}
function confirmCart(fulfillment){const rows=currentLines();if(rows.some(x=>!x.line))throw Error('ตรวจเมนูและราคาที่เปลี่ยนในตะกร้าก่อนค่ะ');const sum=rows.reduce((a,x)=>a+x.line.total,0);sheet('ยืนยันรายการนี้',`<div class="sheet-body"><p class="eyebrow">${fulfillment==='dine_in'?'ทานที่ร้าน':'กลับบ้าน'}</p>${rows.map(x=>`<div class="order-line"><div><h4>${esc(x.line.name)} ${x.line.qty} จาน</h4><p>${esc([...x.line.optionNames,x.line.spice,x.line.note].filter(Boolean).join(' · '))}</p></div><strong>${money(x.line.total)}</strong></div>`).join('')}<div class="cart-summary"><span>ยอดรวม</span><b>${money(sum)}</b></div><p class="small muted">${mode==='practice'?'เมื่อส่งแล้ว ให้กลับไปงานของแม่เพื่อฝึกทำรายการนี้':'แม่จะได้รับรายการเมื่อบันทึกสำเร็จ ชำระเงินที่ร้านค่ะ'}</p><p id="sendError" class="form-error" role="alert"></p></div>`,{footer:`<button class="secondary" data-action="cart">กลับไปแก้</button><button class="primary" data-action="send" data-fulfillment="${fulfillment}">ยืนยันส่งรายการ</button>`});}
async function sendOrder(fulfillment,button){if(busy)return;busy=true;button.disabled=true;let requestId;try{requestId=localStorage.getItem('jele:'+mode+':request')||crypto.randomUUID();localStorage.setItem('jele:'+mode+':request',requestId);}catch{requestId=crypto.randomUUID();}try{const input={requestId,fulfillment,customerId,lines:clone(cart)};let id;if(mode==='practice'){let order;state=await repo.update(old=>{const result=createOrder(old,input);order=result.order;return result.state;});id=order.id;}else{id=await repo.create(input);await reload({renderPage:false});}cart=[];saveCart();closeSheet();go('#/track/'+encodeURIComponent(id));toast(mode==='practice'?'ส่งรายการฝึกแล้ว กลับไปงานของแม่ได้เลยค่ะ':'ส่งรายการเข้าร้านแล้ว');}catch(e){const el=$('#sendError');if(el)el.textContent=friendly(e);else toast(friendly(e));button.disabled=false;}finally{busy=false;render();}}

function showEdit(id,{category:initialCategory=''}={}){
  if(editSaving)return toast('กำลังบันทึกเมนู รอสักครู่ค่ะ');
  const existing=state.menu.find(m=>m.id===id);
  if(!existing&&mode==='live')return sheet('เพิ่มรายชื่อในร้านจริง',`<div class="sheet-body"><p>ระบบกลางของร้านเจ๊เล่ยังต้องรองรับการเก็บเมนูรอเปิดขายก่อน จึงจะเพิ่มรายชื่อจากหน้านี้เข้าร้านจริงได้ค่ะ</p></div>`);
  const d=existing||{id:'custom-'+uuid(),name:'',category:initialCategory||'',description:'',recipe:'',stockKeys:[],price:null,priceMode:'base',groups:[],active:true,published:false,available:true,recommended:false,special:false,photoKey:null};
  currentEdit=d;draftPhoto=null;
  const image=photoUrls.get(d.photoKey),groupPrices=groupsFor(d),isNew=!existing;
  sheet(isNew?'เพิ่มเมนูใหม่':'แก้เมนู '+d.name,`<form id="editForm" data-id="${esc(d.id)}" data-new="${isNew}"><div class="sheet-body"><p class="editor-note">${d.published?'แก้ข้อมูลเมนูที่เปิดขายอยู่':'บันทึกเป็นรายชื่อรอเปิดขายได้ แม้ยังไม่มีภาพหรือราคา'}</p><label class="field">ชื่ออาหาร<input name="name" value="${esc(d.name)}" maxlength="80" required placeholder="พิมพ์ชื่ออาหาร"></label><label class="field">หมวดอาหาร<select name="category" aria-label="หมวดอาหาร" required><option value="">เลือกว่าจะเพิ่มลงหมวดไหน</option>${['yum','som','made','side'].map(id=>`<option value="${id}" ${id===d.category?'selected':''}>${THEMES[id].name}</option>`).join('')}</select></label>${d.priceMode!=='choice'?`<label class="field">ราคาจานนี้ บาท<input type="text" inputmode="decimal" name="price" value="${esc(inputMoney(d.price))}" placeholder="เว้นไว้ก่อนก็ได้" autocomplete="off"></label>`:''}${groupPrices.map((g,gi)=>`<fieldset class="option-group"><legend>${esc(g.name)}<small>${d.priceMode==='choice'&&gi===0?'ราคาขายแต่ละอย่าง เป็นบาท':'ราคาเพิ่ม เป็นบาท'}</small></legend>${g.values.map(v=>`<label class="option-price-row"><span>${esc(v.name)}</span><input class="price-input" name="option-${esc(v.id)}" type="text" inputmode="decimal" value="${esc(inputMoney(d.priceMode==='choice'&&gi===0?v.price:v.delta??0))}" placeholder="รอตั้งราคา" aria-label="ราคา${esc(v.name)}"></label>`).join('')}</fieldset>`).join('')}<label class="field">คำอธิบายเมนู<textarea name="description" maxlength="200" rows="2" placeholder="ไม่บังคับ">${esc(d.description)}</textarea></label><div class="upload-area"><div id="photoPreview">${image?`<img src="${esc(image)}" alt="ภาพ${esc(d.name)}">`:icon('image')}</div><p>ภาพค่อยใส่ทีหลังได้ รับไฟล์ต้นฉบับโดยไม่บังคับความกว้างหรือความสูง</p><label class="secondary">เลือกภาพ<input type="file" id="dishPhoto" accept="image/jpeg,image/png,image/webp" class="sr-only"></label> <button type="button" class="text-button" data-action="remove-photo">เอารูปออก</button><input type="hidden" name="removePhoto" value="0"></div><details class="editor-details" ${d.recipeRequired?'open':''}><summary>รายละเอียดจานและของที่ใช้</summary>${mode==='practice'?`<label class="field">${d.recipeRequired?'ของที่รวมในจาน ต้องระบุก่อนเปิดขาย':'ของในจานหรือคำอธิบายสูตร'}<textarea name="recipe" maxlength="250" rows="2" placeholder="บอกของที่รวมตามสูตรแม่">${esc(d.recipe)}</textarea></label><div class="recipe-checks">${STOCK.map(([key,name])=>`<label><input type="checkbox" name="stockKeys" value="${key}" ${(d.stockKeys||[]).includes(key)?'checked':''}>${name}</label>`).join('')}</div>`:''}<label class="control-row"><span>มีของพร้อมทำ</span><input type="checkbox" name="available" ${d.available!==false?'checked':''}></label><label class="control-row"><span>เป็นจานแนะนำ</span><input type="checkbox" name="recommended" ${d.recommended?'checked':''}></label>${mode==='practice'?`<label class="control-row"><span>เป็นเมนูพิเศษ</span><input type="checkbox" name="special" ${d.special?'checked':''}></label>`:''}</details><p class="form-error" id="editError" role="alert"></p></div></form>`,{footer:`<button class="secondary" data-action="close">ย้อนกลับ</button><button class="primary" type="submit" form="editForm">${d.published?'บันทึกเมนู':'บันทึกรอเปิดขาย'}</button>`});
}
async function saveEdit(form,button){
  if(busy||editSaving)return;
  editSaving=true;const originalLabel=button.textContent;button.disabled=true;button.textContent='กำลังบันทึก…';
  try{
    const d=currentEdit,fd=new FormData(form),groups=clone(d.groups||[]),isNew=form.dataset.new==='true';
    for(let gi=0;gi<groups.length;gi++)for(const v of groups[gi].values){const key=d.priceMode==='choice'&&gi===0?'price':'delta';v[key]=parseBaht(fd.get('option-'+v.id),{allowZero:key==='delta'});if(key==='delta'&&v.delta===null)throw Error('ใส่ราคาเพิ่ม หรือใส่ 0 เมื่อไม่คิดเพิ่ม');}
    const patch={name:String(fd.get('name')||'').trim(),category:String(fd.get('category')||''),description:String(fd.get('description')||'').trim(),price:d.priceMode==='choice'?null:parseBaht(fd.get('price')),groups,available:fd.has('available'),recommended:fd.has('recommended'),special:fd.has('special'),active:true};
    if(mode==='practice'){patch.recipe=String(fd.get('recipe')||'').trim().slice(0,250);patch.stockKeys=fd.getAll('stockKeys');if(isNew)addDish(state,{...patch,id:d.id});else updateDish(state,d.id,patch);}
    if(fd.get('removePhoto')==='1')patch.photoKey=null;
    if(draftPhoto)patch.photoKey=await repo.savePhoto(d.id,draftPhoto);
    const ok=await mutate(isNew?'add-dish':'dish',{id:d.id,patch:isNew?{...patch,id:d.id}:patch});
    if(ok){closeSheet();if(isNew||!d.published){ownerCategory=patch.category;go('#/mother/pending');render();}toast(d.published?'บันทึกเมนูแล้วค่ะ':'บันทึกรายชื่อรอเปิดขายแล้วค่ะ');}
    else if(document.getElementById('editError'))document.getElementById('editError').textContent='ยังไม่ได้บันทึก ตรวจข้อความแจ้งด้านบนแล้วลองอีกครั้งค่ะ';
  }catch(e){if(document.getElementById('editError'))document.getElementById('editError').textContent=friendly(e);}
  finally{editSaving=false;if(button.isConnected){button.disabled=false;button.textContent=originalLabel;}}
}
function publishSheet(id){
  const d=state.menu.find(d=>d.id===id);
  if(!d||!dishConfigured(state,d))return toast('ตั้งราคาและตรวจของในจานให้พร้อมก่อนค่ะ');
  sheet('เปิดขายเมนูนี้',`<div class="sheet-body"><h3>${esc(d.name)}</h3><p>${esc(THEMES[d.category].name)}</p><p class="saved-price">${savedPrices(d).map(v=>`${v.name?esc(v.name)+' ':''}${money(v.price)}`).join(' · ')}</p><p>เมื่อยืนยัน เมนูนี้จะแสดงในหน้าลูกค้า ${mode==='practice'?'ของพื้นที่ฝึกนี้':'ของร้านเจ๊เล่'} และสั่งได้เมื่อเปิดร้านค่ะ</p></div>`,{footer:`<button class="secondary" data-action="close">เก็บรอไว้ก่อน</button><button class="primary" data-action="publish-confirm" data-id="${esc(id)}">ยืนยันเปิดขาย</button>`});
}
function unpublishSheet(id){const d=state.menu.find(d=>d.id===id);if(!d)return;sheet('เก็บเมนูไว้รอเปิดขาย',`<div class="sheet-body"><h3>${esc(d.name)}</h3><p>ชื่อ ราคา และภาพยังอยู่ครบ รายการที่ลูกค้าสั่งมาแล้วจะยังอยู่ค่ะ</p></div>`,{footer:`<button class="secondary" data-action="close">กลับไปก่อน</button><button class="primary" data-action="unpublish-confirm" data-id="${esc(id)}">ยืนยันเก็บรอเปิดขาย</button>`});}
function showCatalog(){if(mode==='live')return sheet('รายชื่อในร้านจริง',`<div class="sheet-body"><p>รายชื่อเพิ่มเติมต้องผูกกับหมวดและร้านเจ๊เล่ในระบบกลางก่อนค่ะ</p></div>`);catalogSearch='';sheet('เลือกรายชื่อเพิ่มเติม',`<div class="sheet-body"><p class="small muted">รายชื่ออาหารเพิ่มเติมสำหรับเลือกเก็บไว้ เมนูที่เพิ่มจะยังอยู่ในหน้ารอเปิดขายค่ะ</p><label class="search">${icon('search')}<input type="search" id="catalogSearch" placeholder="ค้นหาชื่ออาหาร" aria-label="ค้นหาอาหารที่จะเพิ่ม"></label><div id="catalogRows">${catalogRows()}</div></div>`);}
function catalogRows(){const list=state.menu.filter(d=>!d.active&&(!catalogSearch||d.name.includes(catalogSearch)));return list.length?list.map(d=>`<div class="setting-row"><div class="setting-text"><h3>${esc(d.name)}</h3><p>${CATEGORIES.find(([id])=>id===d.category)?.[1]}</p></div><button class="secondary" data-action="catalog-add" data-id="${esc(d.id)}">เพิ่มเมนูนี้</button></div>`).join(''):empty('ไม่พบเมนูเพิ่ม','ลองค้นชื่อสั้นลงได้ค่ะ');}
function stockSheet(key){const available=state.stock[key]===false,name=STOCK.find(([id])=>id===key)?.[1],impacts=stockImpact(state,key);sheet(available?'กลับมาขาย'+name:name+'หมดวันนี้',`<div class="sheet-body"><p>${available?'เมนูที่ผูกวัตถุดิบนี้จะกลับมาสั่งได้ เมื่อราคาและของอื่นพร้อม':'ปิดเฉพาะเมนูหรือตัวเลือกที่ผูกวัตถุดิบนี้ไว้ รายการที่สั่งแล้วจะยังอยู่'}</p><h3 class="small">เมนูและตัวเลือกที่ได้รับผล</h3>${impacts.length?`<ul class="small">${impacts.map(n=>`<li>${esc(n)}</li>`).join('')}</ul>`:'<p class="small muted">ยังไม่มีเมนูที่ผูกวัตถุดิบนี้</p>'}<p class="small muted">ตรวจจานรวมให้แม่ระบุของที่ใช้ก่อนเปิดขายเสมอค่ะ</p></div>`,{footer:`<button class="secondary" data-action="close">ยังไม่เปลี่ยน</button><button class="primary" data-action="stock-confirm" data-key="${key}" data-available="${available}">${available?'กลับมาขาย':'ปิดของที่หมด'}</button>`});}
function showPayment(id,finish=true){const o=state.orders.find(x=>x.id===id);if(!o)return;sheet(o.paid?'ส่งอาหารครบแล้ว':'รับเงินรายการ '+o.code,`<form id="payForm" data-id="${esc(id)}" data-finish="${finish}"><div class="sheet-body">${orderLines(o)}<div class="cart-summary"><span>${o.paid?'รับเงินแล้ว':'ยอดที่ต้องรับ'}</span><b>${money(o.total)}</b></div>${o.paid?'<p>ตรวจอาหารให้ครบแล้วจบการส่งมอบได้เลย ไม่เพิ่มรายรับซ้ำค่ะ</p>':`${mode==='live'?`<input type="hidden" name="method" value="${esc(o.paymentMethod||'')}"><p class="small">ช่องทางรับเงิน: ${o.paymentMethod==='cash'?'เงินสด':o.paymentMethod==='promptpay_qr'?'สแกนจ่ายหน้าร้าน':'ตามรายการที่ลูกค้าเลือก'}</p>`:'<label class="field">รับเงินแบบไหน<select name="method"><option value="cash">เงินสด</option><option value="promptpay_qr">สแกนจ่ายหน้าร้าน</option></select></label>'}<p class="small">ตรวจว่าได้รับเงินจริงแล้วก่อนกดยืนยันค่ะ</p>`}<p class="form-error" id="payError" role="alert"></p></div></form>`,{footer:`<button class="secondary" data-action="close">ย้อนกลับ</button><button class="primary" type="submit" form="payForm">${o.paid?'ยืนยันส่งอาหารแล้ว':finish?'ยืนยันรับเงินและจบรายการ':'ยืนยันรับเงินก่อน'}</button>`});}
function orderMore(id){const o=state.orders.find(x=>x.id===id);if(!o)return;sheet('เพิ่มเติม '+o.code,`<div class="sheet-body">${!o.paid?`<button class="secondary wide" style="margin-bottom:13px" data-action="prepay" data-id="${esc(id)}">รับเงินไว้ก่อน</button>`:''}<button class="secondary wide" style="margin-bottom:13px" data-action="sold-out" data-id="${esc(id)}">แจ้งของหมดในรายการนี้</button><button class="text-button wide" style="color:var(--red)" data-action="cancel-sheet" data-id="${esc(id)}">ยกเลิกรายการ</button></div>`);}
function cancelSheet(id){const o=state.orders.find(x=>x.id===id);if(!o)return;sheet('ยกเลิกรายการ '+o.code,`<form id="cancelForm" data-id="${esc(id)}"><div class="sheet-body">${o.paid?`<div class="notice warning">รายการนี้รับเงินแล้ว ${money(o.total)} เมื่อยกเลิกจะมีงานคืนเงินค้างให้ตรวจค่ะ</div>`:''}<label class="field">เหตุผลที่ยกเลิก<textarea name="reason" maxlength="200" required placeholder="เช่น กุ้งหมด ลูกค้าเลือกเปลี่ยนเมนู"></textarea></label><p class="small muted">ลูกค้าจะเห็นเหตุผลนี้ค่ะ</p><p id="cancelError" class="form-error" role="alert"></p></div></form>`,{footer:`<button class="secondary" data-action="close">ไม่ยกเลิก</button><button class="danger" type="submit" form="cancelForm">ยืนยันยกเลิก</button>`});}
function refundSheet(id){const o=state.orders.find(x=>x.id===id);if(!o?.refund)return;sheet('บันทึกคืนเงินแล้ว',`<div class="sheet-body"><p>รายการ ${esc(o.code)}</p><div class="cart-summary"><span>เงินที่ต้องคืน</span><b>${money(o.refund.amount)}</b></div><p>กดเมื่อคืนเงินให้ลูกค้าจริงแล้วเท่านั้นค่ะ</p></div>`,{footer:`<button class="secondary" data-action="close">ยังไม่คืน</button><button class="primary" data-action="refund-confirm" data-id="${esc(id)}">ยืนยันคืนเงินแล้ว</button>`});}
function closeDaySheet(){const s=getSummary();sheet('ตรวจยอดก่อนจบวัน',`<div class="sheet-body"><div class="closing-row"><span>รับเงินแล้ว</span><b>${money(s.received)}</b></div><div class="closing-row"><span>คืนเงินแล้ว</span><b>${money(s.refunded)}</b></div><div class="closing-row"><span>รับเงินสุทธิ</span><b>${money(s.net)}</b></div><div class="closing-row"><span>รายการค้าง</span><b>${s.pendingCount} รายการ</b></div>${s.refundDue?`<div class="notice warning">ยังมีเงินที่ต้องคืน ${money(s.refundDue)}</div>`:''}<p class="small muted" style="margin-top:19px">ปิดรับรายการใหม่และเก็บยอดไว้ดูย้อนหลัง วันถัดไปแม่กดเปิดร้านเมื่อพร้อมค่ะ</p>${s.pendingCount?'<p class="form-error">ยังจบวันไม่ได้ ตรวจรายการค้างให้ครบก่อนค่ะ</p>':''}</div>`,{footer:`<button class="secondary" data-action="close">กลับไปตรวจ</button><button class="primary" data-action="close-confirm" ${s.pendingCount||s.refundDue?'disabled':''}>ยืนยันจบวัน</button>`});}
function liveInfo(){sheet('การเชื่อมร้านเจ๊เล่',`<div class="sheet-body">${liveConfigured()?'<p>มีการกำหนดร้านเจ๊เล่ไว้แล้ว เข้างานร้านด้วยบัญชีที่มีสิทธิ์ของแม่เพื่อตรวจและใช้ข้อมูลร้านจริงค่ะ</p><button class="primary wide" data-action="live-mode">เปิดร้านที่เชื่อมระบบกลาง</button>':'<p>หน้านี้ต่ออยู่ในโครงการระบบเดิมแล้ว แต่ยังไม่ได้ผูกรหัสร้านเจ๊เล่กับฐานข้อมูลกลาง จึงเปิดให้ฝึกในเครื่องก่อนค่ะ</p><p>ก่อนรับรายการจริง ต้องเพิ่มหรือเลือกร้านเจ๊เล่ในระบบกลาง ผูกบัญชีแม่ และตั้งราคาให้จานที่ขายครบ</p><a class="secondary wide" href="../#/exec">เปิดระบบกลางของคุณ</a>'}<p class="small muted" style="margin-top:18px">ข้อมูลร้านคุณยุ้ยยังอยู่ในระบบเดิม แยกจากพื้นที่ฝึกร้านเจ๊เล่ค่ะ</p></div>`);}
function showLogin(error=''){const target=$('#app');target.innerHTML=`<div class="narrow"><p class="eyebrow">งานร้านเจ๊เล่</p><h1>เข้าสู่งานของแม่</h1><p class="muted">ใช้บัญชีร้านที่ผูกกับระบบกลางเดิมค่ะ</p><form id="loginForm"><label class="field">อีเมล<input type="email" name="email" autocomplete="username" required></label><label class="field">รหัสผ่าน<input type="password" name="password" autocomplete="current-password" required></label><p class="form-error" id="loginError" role="alert">${esc(error)}</p><button class="primary wide" type="submit">เข้าสู่งานร้าน</button></form><button class="text-button wide" data-action="practice-mode">กลับไปพื้นที่ฝึก</button></div>`;$('#bottomArea').innerHTML='';}
function preserveInput(id,fn){const input=document.getElementById(id),selection=input?.selectionStart;fn();const next=document.getElementById(id);if(next){next.focus({preventScroll:true});if(next.type!=='search')next.setSelectionRange(selection,selection);}}
document.addEventListener('input',e=>{if(e.target.id==='menuSearch'){search=e.target.value;preserveInput('menuSearch',render);}else if(e.target.id==='ownerSearch'){ownerSearch=e.target.value;preserveInput('ownerSearch',render);}else if(e.target.id==='catalogSearch'){catalogSearch=e.target.value;$('#catalogRows').innerHTML=catalogRows();}});

async function saveShopBanner(file,input){
  if(!file||bannerSaving)return;
  if(!['image/jpeg','image/png','image/webp'].includes(file.type)){input.value='';return toast('เลือกภาพ JPG PNG หรือ WEBP ค่ะ');}
  if(busy){input.value='';return toast('รอบันทึกงานก่อน แล้วเลือกภาพอีกครั้งค่ะ');}
  bannerSaving=true;
  const preview=URL.createObjectURL(file);
  const previousKey=state.settings.bannerPhotoKey;
  const changeButton=document.querySelector('.shop-banner-change');
  if(changeButton){changeButton.disabled=true;changeButton.textContent='กำลังบันทึกภาพ…';}
  try{
    await new Promise((resolve,reject)=>{const image=new Image();image.onload=()=>image.naturalWidth&&image.naturalHeight?resolve():reject(Error('เปิดภาพนี้ไม่ได้ กรุณาเลือกไฟล์ภาพอีกครั้งค่ะ'));image.onerror=()=>reject(Error('เปิดภาพนี้ไม่ได้ กรุณาเลือกไฟล์ภาพอีกครั้งค่ะ'));image.src=preview;});
    const photoKey=await repo.savePhoto('__shop-banner__',file);
    const ok=await mutate('shop-banner',{photoKey});
    if(ok){
      if(previousKey&&previousKey!==photoKey&&photoUrls.has(previousKey)){URL.revokeObjectURL(photoUrls.get(previousKey));photoUrls.delete(previousKey);}
      toast(mode==='live'?'บันทึกโปสเตอร์ร้านแล้วค่ะ':'บันทึกโปสเตอร์ร้านในเครื่องนี้แล้วค่ะ');
    }
  }catch(error){toast(friendly(error));}
  finally{URL.revokeObjectURL(preview);input.value='';bannerSaving=false;if(changeButton?.isConnected){changeButton.disabled=false;changeButton.textContent='เปลี่ยนภาพ';}}
}

document.addEventListener('change',async e=>{if(e.target.id==='shopBannerUpload'){await saveShopBanner(e.target.files?.[0],e.target);return;}if(e.target.closest('#dishForm'))dishTotal();if(e.target.id==='dishPhoto'){const file=e.target.files?.[0];if(!file)return;if(!['image/jpeg','image/png','image/webp'].includes(file.type)){e.target.value='';toast('เลือกภาพ JPG PNG หรือ WEBP ค่ะ');return;}draftPhoto=file;if(draftPreview)URL.revokeObjectURL(draftPreview);draftPreview=URL.createObjectURL(file);$('#photoPreview').innerHTML=`<img src="${draftPreview}" alt="ภาพที่แม่เลือก ยังไม่บันทึก">`;$('#editForm [name="removePhoto"]').value='0';}});
document.addEventListener('submit',async e=>{const form=e.target;if(!['dishForm','cartForm','editForm','payForm','cancelForm','loginForm'].includes(form.id))return;e.preventDefault();try{if(form.id==='dishForm'){const l=selectedDish();lineFor(state,l.dishId,l);const same=cart.find(x=>x.dishId===l.dishId&&x.note===l.note&&x.spice===l.spice&&JSON.stringify(x.selected)===JSON.stringify(l.selected));if(same){if(same.qty+l.qty>99)throw Error('จานนี้ในตะกร้าครบ 99 แล้ว');same.qty+=l.qty;}else cart.push(l);saveCart();closeSheet();render();toast('ใส่อาหารในตะกร้าแล้วค่ะ');}else if(form.id==='cartForm')confirmCart(new FormData(form).get('fulfillment'));else if(form.id==='editForm')await saveEdit(form,document.querySelector('[form="editForm"]'));else if(form.id==='payForm'){const ok=await mutate('pay',{id:form.dataset.id,finish:form.dataset.finish==='true',method:new FormData(form).get('method')||'cash'});if(ok){closeSheet();toast('บันทึกรับเงินเรียบร้อยค่ะ');}}else if(form.id==='cancelForm'){const ok=await mutate('cancel',{id:form.dataset.id,reason:new FormData(form).get('reason')});if(ok){closeSheet();toast('ยกเลิกรายการแล้วค่ะ');}}else if(form.id==='loginForm'){const btn=form.querySelector('button');btn.disabled=true;try{const fd=new FormData(form);await repo.login(String(fd.get('email')).trim(),String(fd.get('password')));form.reset();await reload();toast('เข้างานร้านเจ๊เล่แล้วค่ะ');}catch(error){$('#loginError').textContent=friendly(error);btn.disabled=false;}}}catch(error){const errorId=form.id==='dishForm'?'dishError':form.id==='cartForm'?'cartError':null;if(errorId&&document.getElementById(errorId))document.getElementById(errorId).textContent=friendly(error);else toast(friendly(error));}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const a=b.dataset.action,id=b.dataset.id;try{switch(a){case'close':closeSheet();break;case'cart':showCart();break;case'dish':showDish(id);break;case'category':category=b.dataset.value;foodView='all';render();break;case'food-view':foodView=b.dataset.value;category='all';render();break;case'owner-category':ownerCategory=b.dataset.value;render();break;case'orders':go('#/orders');break;case'track':go('#/track/'+encodeURIComponent(id));break;case'qty-minus':dishQty=Math.max(1,dishQty-1);dishTotal();break;case'qty-plus':dishQty=Math.min(99,dishQty+1);dishTotal();break;case'cart-minus':{const i=Number(b.dataset.index);if(cart[i]){cart[i].qty--;if(cart[i].qty<1)cart.splice(i,1);saveCart();render();showCart();}break;}case'cart-plus':{const i=Number(b.dataset.index);if(cart[i]){cart[i].qty=Math.min(99,cart[i].qty+1);saveCart();render();showCart();}break;}case'cart-remove':cart.splice(Number(b.dataset.index),1);saveCart();render();showCart();break;case'send':await sendOrder(b.dataset.fulfillment,b);break;case'open':if(await mutate('open'))toast('เปิดรับรายการแล้วค่ะ');break;case'pause':if(await mutate('pause'))toast('พักรับรายการใหม่แล้ว รายการเดิมยังอยู่ค่ะ');break;case'order-filter':filter=b.dataset.value;render();break;case'advance':b.disabled=true;if(await mutate('advance',{id}))toast('เปลี่ยนสถานะแล้วค่ะ');break;case'pay-sheet':showPayment(id);break;case'deliver':showPayment(id);break;case'prepay':showPayment(id,false);break;case'order-more':orderMore(id);break;case'cancel-sheet':cancelSheet(id);break;case'refund-sheet':refundSheet(id);break;case'refund-confirm':if(await mutate('refund',{id})){closeSheet();toast('บันทึกคืนเงินแล้วค่ะ');}break;case'edit':showEdit(id);break;case'new-dish':showEdit(null,{category:b.dataset.category||''});break;case'publish-sheet':publishSheet(id);break;case'publish-confirm':if(await mutate('publish',{id})){closeSheet();toast('เปิดขายเมนูนี้แล้วค่ะ');}break;case'unpublish-sheet':unpublishSheet(id);break;case'unpublish-confirm':if(await mutate('unpublish',{id})){closeSheet();toast('เก็บไว้ในรายชื่อรอเปิดขายแล้วค่ะ');}break;case'catalog':showCatalog();break;case'catalog-add':if(await mutate('dish',{id,patch:{active:true}})){showEdit(id);toast('เพิ่มไว้ให้แล้ว ตั้งราคาได้เลยค่ะ');}break;case'stock':stockSheet(b.dataset.key);break;case'stock-confirm':if(await mutate('stock',{key:b.dataset.key,available:b.dataset.available==='true'})){closeSheet();toast('เปลี่ยนของที่มีขายแล้วค่ะ');}break;case'sold-out':sheet('ของหมดในรายการนี้',`<div class="sheet-body"><p>ปิดของที่หมดในเมนูก่อน แล้วแจ้งลูกค้าเพื่อเลือกเปลี่ยนหรือยกเลิกรายการค่ะ รายการเดิมจะไม่หายเอง</p><a class="primary wide" href="#/mother/pending" data-action="navigate-close">ไปปิดของที่หมด</a><button class="text-button wide" data-action="cancel-sheet" data-id="${esc(id)}">ยกเลิกรายการนี้พร้อมเหตุผล</button></div>`);break;case'navigate-close':closeSheet();break;case'remove-photo':draftPhoto=null;if(draftPreview)URL.revokeObjectURL(draftPreview);draftPreview=null;$('#photoPreview').innerHTML=icon('image');$('#editForm [name="removePhoto"]').value='1';break;case'close-day':closeDaySheet();break;case'close-confirm':if(await mutate('close')){closeSheet();toast('เก็บยอดวันนี้แล้วค่ะ');}break;case'live-info':liveInfo();break;case'live-mode':if(!liveConfigured())return liveInfo();mode='live';try{localStorage.setItem('jele:mode',mode);}catch{}repo=new PlatformRepository();closeSheet();readCart();go('#/mother');await reload();break;case'practice-mode':mode='practice';try{localStorage.setItem('jele:mode',mode);}catch{}repo=practice;closeSheet();readCart();await reload();go('#/mother');break;case'logout':{if(livePollTimer)clearInterval(livePollTimer);livePollTimer=null;loadRevision++;await repo.logout();loadRevision++;state=null;photoUrls.clear();showLogin();break;}case'reset-practice':sheet('เริ่มข้อมูลฝึกใหม่',`<div class="sheet-body"><p>เอาราคา รูป และรายการฝึกในเครื่องนี้ออก แล้วเริ่มจากเมนูรอตั้งราคาอีกครั้ง ข้อมูลร้านจริงและร้านคุณยุ้ยไม่เปลี่ยนค่ะ</p></div>`,{footer:'<button class="secondary" data-action="close">เก็บไว้ก่อน</button><button class="danger" data-action="reset-confirm">เริ่มฝึกใหม่</button>'});break;case'reset-confirm':state=await practice.reset();cart=[];saveCart();closeSheet();go('#/mother/menu');render();toast('เริ่มข้อมูลฝึกใหม่แล้วค่ะ');break;}}catch(error){if(mode==='live'&&isMother()&&isAuthFailure(error))showLogin(friendly(error));else toast(friendly(error));}});
window.addEventListener('hashchange',async()=>{window.scrollTo({top:0,behavior:'instant'});if(mode==='live'){try{await reload();}catch(e){showLiveFailure(e);}}else render();});
practice.subscribe(async()=>{if(mode!=='practice')return;await reload({renderPage:!$('#sheet').open});});
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible'&&!$('#sheet').open)reload().catch(e=>toast(friendly(e)));});
async function start(){
  readCart();
  $('#modeBand').textContent=mode==='live'?'ร้านเจ๊เล่ · กำลังเชื่อมต่อ':'พื้นที่ฝึกใช้งาน · รายการและเงินไม่เข้าร้านจริง';
  try{repo=mode==='live'?new PlatformRepository():practice;await reload();}
  catch(error){
    if(mode==='live'){showLiveFailure(error);}
    else{$('#app').innerHTML='<div class="error-view"><h1>ยังเปิดพื้นที่ฝึกไม่ได้</h1><p>'+esc(friendly(error))+'</p><button class="primary" data-action="retry-load">ลองเปิดใหม่</button></div>';}
  }
}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="retry-load"]'))location.reload();});
initBannerViewer();
await start();
